mapper.select:
SELECT 
FROM author_chapter_draft d
JOIN book b ON b.id = d.book_id
LEFT JOIN author_book_collaborator c
  ON c.book_id = d.book_id AND c.collaborator_author_id = #{authorId}
WHERE d.author_id = #{authorId}
  AND (b.author_id = #{authorId} OR c.can_manage_chapters = 1)

    AND d.status = #{status}

ORDER BY d.update_time DESC, d.id DESC
LIMIT #{offset}, #{limit}

SELECT COUNT(*)
FROM author_chapter_draft d
JOIN book b ON b.id = d.book_id
LEFT JOIN author_book_collaborator c
  ON c.book_id = d.book_id AND c.collaborator_author_id = #{authorId}
WHERE d.author_id = #{authorId}
  AND (b.author_id = #{authorId} OR c.can_manage_chapters = 1)

    AND d.status = #{status}

SELECT 
FROM author_chapter_draft
WHERE status = 'SCHEDULED' AND scheduled_at <= #{now}
ORDER BY scheduled_at, id
LIMIT #{limit}

mapper.update:
UPDATE author_chapter_draft
SET status = 'PUBLISHING', last_error = NULL, version = version + 1
WHERE id = #{id} AND author_id = #{authorId} AND version = #{expectedVersion} AND status = #{fromStatus}

UPDATE author_chapter_draft
SET last_error = #{message}
WHERE id = #{id} AND status = 'SCHEDULED'
